/**
 * S-30 T-354: every agent still on LegacyMapper must reach its CLI exactly as
 * it did BEFORE the refactor. The oracle is `__fixtures__/pre-s30-golden.json`,
 * generated by running the pre-S-30 code (commit 134df123) through
 * `tools/legacy-equivalence/generate-golden.cjs`: argv, stdin and the native
 * MCP config its injectors wrote, for each agent × mode × fresh/resumed run.
 */
import { describe, it, expect, vi, beforeAll } from 'vitest';
import { EventEmitter } from 'node:events';
import * as fs from 'node:fs';
import * as os from 'node:os';
import * as path from 'node:path';

interface Captured { args: string[]; stdio0: string; stdin: string[] }
let captured: Captured | null = null;
vi.mock('node:child_process', () => ({
  spawn: vi.fn((_command: string, args: string[], options: { stdio: string[] }) => {
    const proc = new EventEmitter() as EventEmitter & Record<string, unknown>;
    const writes: string[] = [];
    proc['stdin'] = { write: (c: unknown) => { writes.push(String(c)); return true; }, end: () => undefined, on: () => proc['stdin'], once: () => proc['stdin'] };
    proc['stdout'] = new EventEmitter();
    proc['stderr'] = new EventEmitter();
    proc['pid'] = 1;
    proc['kill'] = () => true;
    captured = { args: [...args], stdio0: options.stdio[0] ?? '', stdin: writes };
    return proc;
  }),
}));

import type { RunId } from '../../../../../shared/domain/agent';
import { buildDefaultCapabilities, type RunMode } from '../../../../../shared/domain/run-capabilities';
import { ChildProcessCliLauncher } from '../../../cli-adapters/infrastructure/cli-launcher';
import { AGENT_DEFS } from '../../../cli-adapters/infrastructure/registry';
import { MemoryMcpInjector } from '../../../memory/mcp-server/memory-mcp-injector';
import { KanbanMcpInjector } from '../../../sdd/mcp-server/kanban-mcp-injector';
import { UiMcpInjector } from '../../../ui-tools/mcp-server/ui-mcp-injector';
import type { DeliveryResolution } from '../../domain';
import { NativeConfigMcpDelivery } from '../../shared/native-config-mcp';
import { makeRunPlan } from '../../testing/make-run-plan';
import { LegacyMapper } from './legacy-mapper';

interface GoldenCase { agentId: string; mode: RunMode; resume: boolean; spawn: Captured | { error: string } | null }
interface Golden { cases: GoldenCase[]; nativeConfig: Record<string, Record<string, string>> }

const golden = JSON.parse(
  fs.readFileSync(path.join(__dirname, '__fixtures__', 'pre-s30-golden.json'), 'utf8'),
) as Golden;

// Same fixed inputs as tools/legacy-equivalence/cases.cjs.
const INPUT = {
  cwd: '/ws/proj', workspaceRoot: '/ws', prompt: 'PROMPT', systemPrompt: 'SYS', model: 'm1', reasoning: 'high',
  runId: 'run-1', resumeSessionId: 'sess-1', uiDir: '/tmp/devia-ui/run-1', deviaDir: '/home/u/.devia-app',
  uiTools: ['ask_user', 'todo'] as const,
};
const NO_MCP: DeliveryResolution = { mcpServerIds: [], skills: 'none', subagents: 'none', notices: [] };
const deps = { nativeMcp: { deliver: () => ({ file: null, deliveredServerIds: [] }) } };

function spawnNew(c: GoldenCase): Captured | { error: string } | null {
  const def = AGENT_DEFS.find((d) => d.id === c.agentId);
  if (!def) throw new Error(`unknown agent ${c.agentId}`);
  const mapper = new LegacyMapper(def, deps);
  const plan = makeRunPlan({
    runId: INPUT.runId, agentId: def.id, mode: c.mode, cwd: INPUT.cwd, projectCheckout: INPUT.cwd,
    prompt: INPUT.prompt, model: INPUT.model, reasoning: INPUT.reasoning,
    extraAllowedDirs: c.mode !== 'apply-yolo' ? [INPUT.workspaceRoot] : [],
    ...(c.resume && { resumeSessionId: INPUT.resumeSessionId }),
    capabilities: buildDefaultCapabilities(INPUT.runId as RunId, c.mode, { defaultDisallowedTools: [...mapper.disallowedTools(c.mode)] }),
  });
  const prepared = mapper.prepareRun(plan, INPUT.systemPrompt, NO_MCP);
  if (!prepared.ok) return { error: prepared.error };
  captured = null;
  let error: string | null = null;
  new ChildProcessCliLauncher().launch(
    { def, cwd: plan.cwd, prepared: prepared.run, openSession: (io) => mapper.openSession(io, plan), runId: plan.runId, mode: c.mode },
    { onOutput: () => undefined, onDone: () => undefined, onError: (m) => { error = m; }, onUiRequest: () => false },
  );
  prepared.run.cleanup();
  return error !== null && captured === null ? { error } : captured;
}

/** The compiled server's location differs between the old dist and these sources. */
function normalisePaths(text: string): string {
  return text.replace(/"[^"]*\/(memory|sdd|ui-tools)\/mcp-server\/server\.js"/g, '"<$1>/server.js"');
}

/** A config file as a comparable value: JSON parsed (key order is irrelevant), TOML as a set of blocks. */
function semantic(file: string, content: string): unknown {
  let text = normalisePaths(content);
  // process.execPath differs between local (nvm) and CI (hostedtoolcache) — neutralise it.
  text = text.replace(/"[^"]*\/bin\/node"/g, '"<*NODE*>"');
  if (file.endsWith('.json')) {
    const parsed = JSON.parse(text) as { mcp?: { servers?: Array<{ id: string }> } };
    // grok keeps servers in an ARRAY: the order is the write order (three
    // injector writes before, one delivery now), not configuration.
    parsed.mcp?.servers?.sort((a, b) => a.id.localeCompare(b.id));
    return parsed;
  }
  return text.split(/\n(?=# devia-mcp-start )/).map((b) => b.trim()).filter(Boolean).sort();
}

describe('LegacyMapper is equivalent to the pre-S-30 pipeline (T-354)', () => {
  beforeAll(() => vi.useFakeTimers());

  it('covers every agent still on LegacyMapper', () => {
    expect(new Set(golden.cases.map((c) => c.agentId)).size).toBeGreaterThanOrEqual(10);
  });

  it.each(golden.cases.map((c) => [`${c.agentId} ${c.mode}${c.resume ? ' resumed' : ''}`, c] as const))(
    '%s: same argv, stdin and stdio',
    (_name, c) => {
      expect(spawnNew(c)).toEqual(c.spawn);
    },
  );

  it.each(Object.entries(golden.nativeConfig))('%s: same Devia MCP servers in its native config', (agentId, expected) => {
    const project = fs.mkdtempSync(path.join(os.tmpdir(), 'devia-equiv-'));
    try {
      const servers = [
        new KanbanMcpInjector(() => INPUT.deviaDir).serverConfig(INPUT.cwd),
        new MemoryMcpInjector(() => INPUT.deviaDir).serverConfig(INPUT.cwd, agentId),
        new UiMcpInjector().serverConfig(INPUT.uiDir, INPUT.uiTools),
      ];
      new NativeConfigMcpDelivery(undefined, () => project).deliver(agentId, project, servers);
      const actual: Record<string, unknown> = {};
      const walk = (dir: string): void => {
        for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
          const full = path.join(dir, e.name);
          if (e.isDirectory()) walk(full);
          else actual[path.relative(project, full)] = semantic(e.name, fs.readFileSync(full, 'utf8').split(project).join('<P>'));
        }
      };
      walk(project);
      const expectedSemantic = Object.fromEntries(
        Object.entries(expected).map(([f, content]) => [f, semantic(f, content.replace(/\/[^"\s]*devia-golden-[A-Za-z0-9]+/g, '<P>'))]),
      );
      expect(actual).toEqual(expectedSemantic);
    } finally {
      fs.rmSync(project, { recursive: true, force: true });
    }
  });
});
